import Image from "next/image";
import { getCurrentUser, listUsers } from "@/lib/users";
import { listNotesForUser } from "@/lib/notes";
import { NewNoteForm } from "./NewNoteForm";
import { NoteImageUpload } from "./NoteImageUpload";

export default async function DashboardPage() {
  const me = await getCurrentUser();
  const all = await listUsers();
  const notes = me ? await listNotesForUser(me.id) : [];

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>

      <h2 className="mt-8 text-lg font-medium">Notes</h2>
      <ul className="mt-2 space-y-4">
        {notes.map((note) => (
          <li
            key={note.id}
            className="rounded border border-black/10 p-3 dark:border-white/20"
          >
            <p className="text-sm font-medium">{note.title}</p>
            {note.body && (
              <p className="mt-1 text-sm opacity-80">{note.body}</p>
            )}
            {note.imageUrl ? (
              <Image
                src={note.imageUrl}
                alt={note.title}
                width={320}
                height={200}
                unoptimized
                className="mt-2 max-h-48 w-auto rounded object-cover"
              />
            ) : (
              <NoteImageUpload noteId={note.id} />
            )}
          </li>
        ))}
        {notes.length === 0 && (
          <li className="text-sm opacity-70">No notes yet.</li>
        )}
      </ul>

      <NewNoteForm />
    </main>
  );
}

